import os, re
def imports(m):
    p = m.replace('.', '/') + '.lean'
    return re.findall(r'^import\s+(AlgebraicJacobian[\w.]*)', open(p).read(), re.M) if os.path.exists(p) else []
def closure(seed):
    seen, stack = set(), [seed]
    while stack:
        m = stack.pop()
        if m not in seen:
            seen.add(m); stack += imports(m)
    return seen
disk={os.path.join(r,f)[:-5].replace('/','.') for r,_,fs in os.walk('AlgebraicJacobian') for f in fs if f.endswith('.lean')}
