import re,glob,subprocess
# collect sorry carriers from build log
carriers=set()
for line in open('/tmp/rootbuild.log'):
    m=re.match(r"warning: (\S+\.lean):(\d+):", line)
    if m and 'declaration uses' in line: carriers.add((m.group(1),int(m.group(2))))
# map carrier file:line -> declaration name
names=set()
for f,ln in carriers:
    try: src=open(f).read().split('\n')
    except: continue
    for i in range(ln-1, max(ln-40,0), -1):
        mm=re.match(r'^(noncomputable |private |protected )*(theorem|lemma|def|instance|abbrev) ([A-Za-z_][A-Za-z0-9_.\']*)', src[i])
        if mm: names.add(mm.group(3)); break
print("sorry-carrier short names:", len(names))
# now scan blueprint for leanok statements pinning one of them
hits=[]
for tex in glob.glob('blueprint/src/chapters/*.tex'):
    t=open(tex).read()
    for m in re.finditer(r'\\lean\{([^}]*)\}', t):
        decls=[d.strip() for d in m.group(1).split(',')]
        s=t.rfind('\\begin{',0,m.start()); e=t.find('\\end{',m.start())
        stmt=t[s:e]
        if '\\leanok' not in stmt: continue
        for d in decls:
            if d.split('.')[-1] in names:
                lab=re.search(r'\\label\{([^}]*)\}', stmt)
                hits.append((tex.split('/')[-1], lab.group(1) if lab else '?', d))
for h in sorted(set(hits)): print('LEANOK on sorry-carrier:', h)
print('total', len(set(hits)))
